html:
{% set margin_summary = doc.margin_summary or {} %}
{% set part_margins = margin_summary.part_margins or [] %}
{% set by_component = margin_summary.by_component or [] %}
{% set total_gm = margin_summary.total_kit_gm or 0 %}
{% set pl = margin_summary.profit_loss if margin_summary.profit_loss is not none else (doc.profit_loss or 0) %}
{% set adjusted = margin_summary.adjusted_gross_margin if margin_summary.adjusted_gross_margin is not none else (pl + total_gm) %}
{% set kit_rates = doc.kit_rates %}

<style>
  .xf-print { color: #1a1f2e; }
  .xf-pl-header {
    background: #eef2f9;
    border-bottom: 3px solid #174096;
    color: #0f1d42;
    padding: 14px 18px;
    margin: -8px -8px 16px;
  }
  .xf-pl-header h1 {
    margin: 0;
    font-size: 20px;
    color: #0f1d42 !important;
    line-height: 1.2;
  }
  .xf-pl-header .sub {
    font-size: 10px;
    color: #3d4a66 !important;
    margin-top: 3px;
  }
  .xf-pl-header .brand {
    display: inline-block;
    vertical-align: middle;
  }
  .xf-pl-header img.xf-logo {
    height: 38px;
    width: auto;
    vertical-align: middle;
    margin-right: 12px;
  }
  .xf-pl-meta { font-size: 10px; color: #3d4a66; margin-bottom: 12px; }
  .xf-pl-section {
    font-size: 11px;
    color: #0f1d42 !important;
    font-weight: bold;
    margin: 14px 0 6px;
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }
  .xf-pl-kpi { display: table; width: 100%; margin-bottom: 16px; border-collapse: separate; border-spacing: 6px 0; }
  .xf-pl-kpi .card {
    display: table-cell;
    background: #f5f7fc;
    padding: 10px;
    border: 1px solid #c9d3ea;
    color: #1a1f2e;
  }
  .xf-pl-kpi .lbl { font-size: 8px; color: #5a6580; text-transform: uppercase; }
  .xf-pl-kpi .val { font-size: 13px; font-weight: bold; color: #0f1d42 !important; }
  .xf-pl-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
    margin-bottom: 16px;
    color: #1a1f2e;
  }
  .xf-pl-table th {
    background: #dce4f5 !important;
    color: #0f1d42 !important;
    padding: 6px 8px;
    text-align: left;
    border-bottom: 1px solid #aebcd9;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }
  .xf-pl-table td {
    padding: 6px 8px;
    border-bottom: 1px solid #e4e8f2;
    color: #1a1f2e !important;
  }
  .xf-pl-table .num { text-align: right; color: #1a1f2e !important; }
  .xf-pl-table .total td {
    background: #e8edf8 !important;
    font-weight: bold;
    color: #0f1d42 !important;
  }
  .xf-pl-part-title { font-size: 11px; margin: 14px 0 6px; color: #0f1d42 !important; font-weight: bold; }
  .xf-pl-banner { padding: 12px 16px; margin-top: 12px; border-radius: 4px; }
  .xf-pl-banner.profit { background: #e7f4ed; border: 1px solid #8fc9a8; color: #1e6b3a !important; }
  .xf-pl-banner.loss { background: #fcecea; border: 1px solid #e5a8a8; color: #a0231c !important; }
  .xf-pl-banner .big { font-size: 18px; font-weight: bold; float: right; }
  .xf-gst {
    font-size: 11px;
    font-weight: bold;
    color: #0f1d42 !important;
    background: #e8f6ee;
    border: 1px solid #57bd7c;
    padding: 8px 12px;
    margin: 0 0 14px;
  }
  .xf-pl-note { font-size: 9px; color: #5a6580; margin-top: 4px; }
  .xf-pl-footer {
    font-size: 8px;
    color: #5a6580;
    margin-top: 20px;
    border-top: 1px solid #c9d3ea;
    padding-top: 8px;
  }
</style>

<div class="xf-margin-print xf-print">
<div class="xf-pl-header">
  <table width="100%" cellpadding="0" cellspacing="0"><tr>
    <td style="vertical-align:middle;width:58%">
      <img class="xf-logo" src="data:image/png;base64," alt="Xfloor"/>
      <span class="brand">
        <h1>Xfloor</h1>
        <div class="sub">Margin Report</div>
      </span>
    </td>
    <td style="text-align:right;vertical-align:top">
      <div>{{ doc.project_number or doc.name }}</div>
      <div class="sub">Generated: {{ frappe.utils.formatdate(frappe.utils.nowdate(), "dd MMM yyyy") }}</div>
      {% if kit_rates and kit_rates.rates_effective_date %}<div class="sub">Kit rates as of: {{ frappe.utils.formatdate(kit_rates.rates_effective_date, "dd MMM yyyy") }}</div>{% endif %}
    </td>
  </tr></table>
</div>

<h3 style="margin:0 0 4px;color:#1a1f2e">{{ doc.party_name or "Unnamed project" }}</h3>
<div class="xf-pl-meta">
  {{ (doc.sqft or 0)|int }} sq ft &middot; {{ part_margins|length }} part{{ "s" if part_margins|length != 1 else "" }}
</div>

<div class="xf-pl-section">Same view as Cost Profile</div>
<div class="xf-pl-kpi">
  <div class="card"><div class="lbl">Contract</div><div class="val">{{ frappe.utils.fmt_money(margin_summary.contract_value or doc.contract_value or 0, currency="INR") }}</div></div>
  <div class="card"><div class="lbl">Kit spend</div><div class="val">{{ frappe.utils.fmt_money(margin_summary.total_kit_spend or 0, currency="INR") }}</div></div>
  <div class="card"><div class="lbl">Applicator cost</div><div class="val">{{ frappe.utils.fmt_money(margin_summary.applicator_cost or 0, currency="INR") }}</div></div>
  <div class="card"><div class="lbl">Total Cost</div><div class="val">{{ frappe.utils.fmt_money(margin_summary.total_cost or doc.total_cost or 0, currency="INR") }}</div></div>
  <div class="card"><div class="lbl">Project P&amp;L</div><div class="val">{{ frappe.utils.fmt_money(pl, currency="INR") }}</div></div>
  <div class="card"><div class="lbl">Margin %</div><div class="val">{{ "%.1f"|format(margin_summary.margin_pct or doc.margin_pct or 0) }}%</div></div>
</div>

<div class="xf-pl-section">Add kit gross margin</div>
<div class="xf-pl-kpi">
  <div class="card gm"><div class="lbl">Kit GM earned</div><div class="val">{{ frappe.utils.fmt_money(total_gm, currency="INR") }}</div></div>
  <div class="card gm"><div class="lbl">GM % of kit spend</div><div class="val">{{ "%.1f"|format(margin_summary.gm_pct_of_kit_spend or 0) }}%</div></div>
  <div class="card gm"><div class="lbl">GM % of contract</div><div class="val">{{ "%.1f"|format(margin_summary.gm_pct_of_contract or 0) }}%</div></div>
  <div class="card gm"><div class="lbl">Adjusted gross margin</div><div class="val">{{ frappe.utils.fmt_money(adjusted, currency="INR") }}</div></div>
</div>

{% macro margin_table(rows, totals) %}
<table class="xf-pl-table">
  <thead><tr>
    <th>Component</th><th class="num">Kits</th>
    <th class="num">Rate ₹/kit</th><th class="num">Kit spend</th>
    <th class="num">GM ₹/kit</th><th class="num">GM ₹</th>
    <th class="num">GM % spend</th><th class="num">Share of GM</th>
  </tr></thead>
  <tbody>
    {% for row in rows %}
    <tr>
      <td><b>{{ row.component }}</b></td>
      <td class="num">{{ (row.kits or 0)|int }}</td>
      <td class="num">{{ frappe.utils.fmt_money(row.rate or 0, currency="INR") }}</td>
      <td class="num">{{ frappe.utils.fmt_money(row.kit_spend or 0, currency="INR") }}</td>
      <td class="num">{{ frappe.utils.fmt_money(row.gm_per_kit or 0, currency="INR") }}</td>
      <td class="num">{{ frappe.utils.fmt_money(row.gm_amount or 0, currency="INR") }}</td>
      <td class="num">{{ "%.1f"|format(row.gm_pct_of_spend or 0) }}%</td>
      <td class="num">{{ "%.1f"|format(row.gm_share_pct or 0) }}%</td>
    </tr>
    {% endfor %}
    <tr class="total">
      <td colspan="3" class="num">Total</td>
      <td class="num">{{ frappe.utils.fmt_money(totals.total_kit_spend or 0, currency="INR") }}</td>
      <td></td>
      <td class="num">{{ frappe.utils.fmt_money(totals.total_kit_gm or 0, currency="INR") }}</td>
      <td class="num">{{ "%.1f"|format(totals.gm_pct_of_kit_spend or 0) }}%</td>
      <td class="num">100%</td>
    </tr>
  </tbody>
</table>
{% endmacro %}

{% for part in part_margins %}
  <div class="xf-pl-part-title">{{ part.part_name }} &middot; {{ (part.sqft or 0)|int }} sq ft &middot; P&amp;L {{ frappe.utils.fmt_money(part.profit_loss or 0, currency="INR") }} &middot; Adj. GM {{ frappe.utils.fmt_money(part.adjusted_gross_margin or 0, currency="INR") }}</div>
  {{ margin_table(part.rows or [], part) }}
{% endfor %}

<div class="xf-pl-section">Component profile</div>
{{ margin_table(by_component, margin_summary) }}

<div class="xf-pl-banner {{ 'profit' if adjusted >= 0 else 'loss' }}">
  <span class="big">{{ '+' if adjusted >= 0 else '' }}{{ frappe.utils.fmt_money(adjusted, currency="INR") }}</span>
  <b>ADJUSTED GROSS MARGIN</b><br>
  <span style="font-size:10px">Project P&amp;L {{ frappe.utils.fmt_money(pl, currency="INR") }} + Kit GM {{ frappe.utils.fmt_money(total_gm, currency="INR") }}</span>
</div>

<div class="xf-pl-footer">Xfloor Project Manager &mdash; System Manager only &mdash; Confidential</div>
</div>
